b.add(S4, 329, "management", "Which drug and starting rate are printed under BP control?", "NTG at 5 µg/min", ["Nitroprusside at 50 µg/min", "Dobutamine at 2 µg/kg/min", "Noradrenaline at 0.5 mg/min"], "The line reads DOC: NTG at 5 μg/min.")
b.add(S4, 329, "numeric", "What systolic threshold is printed in the first cardiogenic-shock feature?", "SBP <90 mmHg with narrow pulse pressure", ["SBP <120 mmHg", "DBP <20 mmHg", "Pulse pressure >20 mmHg"], "The feature reads narrow pulse pressure (SBP <90 mm of Hg).")
b.add(S4, 329, "recall", "Which four features follow narrow pulse pressure in cardiogenic shock?", "Fatigue, altered mentation, cyanosis and cold extremities", ["Tachypnea, crepts, frothy sputum and hemoptysis", "Ascites, hepatomegaly, edema and raised JVP", "Angina, syncope, palpitations and fever"], "The remaining features are fatigue, altered mentation, cyanosis and cold extremities; the note adds poor prognosis.")
b.add(S4, 329, "management", "Which two investigations are printed for cardiogenic shock?", "Lactic acid levels to rule out occult shock; early ECHO with ACS exclusion to rule out acute AR and acute MR", ["Coronary angiogram and treadmill test", "Chest X-ray and pulmonary function test", "D-dimer and CT pulmonary angiogram"], "The investigation bullets read lactic acid to r/o occult shock and rule out ACS → early ECHO → rule out acute AR/MR.")
b.add(S4, 329, "match", "Match each HF phenotype to its printed shock support — 1) HFrEF inotrope 2) HFrEF inodilator 3) HFrEF mechanical 4) HFpEF vasopressors … A) Vasopressin/desmopressin B) Intra-aortic balloon pump or ECMO C) Dobutamine (m/c) D) Milrinone (m/c)", "1-C, 2-D, 3-B, 4-A", ["1-D, 2-C, 3-B, 4-A", "1-C, 2-B, 3-D, 4-A", "1-C, 2-D, 3-A, 4-B"], "HFrEF uses dobutamine as the common inotrope, milrinone as the common inodilator and IABP/ECMO support; HFpEF uses vasopressin/desmopressin.")
