# Book p330
b.add(S5, 330, "management", "For pulmonary edema with maintained BP that is not recovering, what intervention is printed?", "Dialysis or SCUF via a central/femoral catheter", ["Immediate TAVR", "Oral naproxen", "Balloon pericardiotomy"], "The note reads patients with pulmonary edema and maintained BP, if not recovering, go to dialysis or SCUF via central/femoral catheter.")
b.add(S5, 330, "fillup", "The expansion printed for SCUF is slow continuous ______.", "ultrafiltration", ["ultrasound filtration", "ultrafractionation", "ultrafiltrate dialysis"], "The parenthesis expands SCUF as slow continuous ultra filtration.")
b.add(S5, 330, "numeric", "Which BNP/NT-proBNP value is printed for patients with a probability of heart failure?", ">900 pg/mL", [">90 pg/mL", ">900 ng/mL", ">300 pg/mL"], "The note reads >900 pg/mL in patients with probability of HF.")
b.add(S5, 330, "recall", "Which two modifiers are printed beneath the BNP/NT-proBNP threshold?", "Levels are lower in obesity because the peptides are metabolised by adipocytes, and the page notes diagnostic value in renal failure", ["Levels are higher in obesity and diagnostic value is lost in renal failure", "Levels are unaffected by adipocytes and measured only in urine", "Levels are lower in renal failure and higher after dialysis"], "The two bullets read lower in obese (metabolised by adipocytes) and diagnostic value in renal failure.")
b.add(S5, 330, "management", "In early vasodilator therapy for acute AR or MR, which drug preference is printed?", "Nitroprusside > NTG (nitroglycerine)", ["NTG > nitroprusside", "Dobutamine > milrinone", "Furosemide > torsemide"], "The early-vasodilator line reads nitroprusside > NTG for acute AR/MR.")
b.add(S5, 330, "recall", "What two-step purpose follows the nitroprusside preference?", "It decreases aortic pressure and thereby decreases the transvalvular gradient in AR/MR", ["It raises aortic pressure and increases the gradient in AR/MR", "It closes the aortic valve and prevents all surgery", "It raises preload and improves coronary steal"], "The arrows read decreases aortic pressure → decreases transvalvular gradient in AR/MR.")
